"use strict";(globalThis.webpackChunkmythogen_engine_blog=globalThis.webpackChunkmythogen_engine_blog||[]).push([[6884],{6498(e,t,n){n.r(t),n.d(t,{assets:()=>h,contentTitle:()=>r,default:()=>l,frontMatter:()=>a,metadata:()=>o,toc:()=>d});var i=n(4848),s=n(8453);const a={},r="FABLE: It's Not Just About Smarter AI \u2014 It's Turning Expert Intuition into Infrastructure",o={id:"TechNotes/FABLE \u4e0d\u53ea\u662f\u667a\u529b\u63d0\u5347\uff0cAI \u6b63\u5728\u628a\u5c08\u5bb6\u76f4\u89ba\u8b8a\u6210\u57fa\u790e\u8a2d\u65bd",title:"FABLE: It's Not Just About Smarter AI \u2014 It's Turning Expert Intuition into Infrastructure",description:"Every time AI's intelligence reaches a certain threshold, a qualitative shift occurs \u2014 not doing the same things better, but suddenly doing things that were previously impossible.",source:"@site/i18n/en/docusaurus-plugin-content-docs/current/TechNotes/FABLE \u4e0d\u53ea\u662f\u667a\u529b\u63d0\u5347\uff0cAI \u6b63\u5728\u628a\u5c08\u5bb6\u76f4\u89ba\u8b8a\u6210\u57fa\u790e\u8a2d\u65bd.md",sourceDirName:"TechNotes",slug:"/TechNotes/FABLE \u4e0d\u53ea\u662f\u667a\u529b\u63d0\u5347\uff0cAI \u6b63\u5728\u628a\u5c08\u5bb6\u76f4\u89ba\u8b8a\u6210\u57fa\u790e\u8a2d\u65bd",permalink:"/en/docs/TechNotes/FABLE \u4e0d\u53ea\u662f\u667a\u529b\u63d0\u5347\uff0cAI \u6b63\u5728\u628a\u5c08\u5bb6\u76f4\u89ba\u8b8a\u6210\u57fa\u790e\u8a2d\u65bd",draft:!1,unlisted:!1,tags:[],version:"current",frontMatter:{},sidebar:"docs",previous:{title:'The New Species of the AI Era: Why Many Companies Are No Longer Looking for "Engineers"?',permalink:"/en/docs/TechNotes/AI \u6642\u4ee3\u7684\u65b0\u7269\u7a2e\uff1a\u70ba\u4ec0\u9ebc\u73fe\u5728\u5f88\u591a\u516c\u53f8\u60f3\u627e\u7684\uff0c\u5df2\u7d93\u4e0d\u662f\u300c\u5de5\u7a0b\u5e2b\u300d\uff1f"},next:{title:"Google Is No Longer Designed for You Either: When Free Models Become the Gateway to Enterprise Cloud",permalink:"/en/docs/TechNotes/Google \u4e5f\u4e0d\u518d\u70ba\u4f60\u800c\u8a2d\u8a08\uff1a\u7576\u514d\u8cbb\u6a21\u578b\u8b8a\u6210\u4f01\u696d\u96f2\u7aef\u7684\u5165\u53e3"}},h={},d=[];function c(e){const t={h1:"h1",header:"header",hr:"hr",img:"img",p:"p",...(0,s.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(t.header,{children:(0,i.jsx)(t.h1,{id:"fable-its-not-just-about-smarter-ai--its-turning-expert-intuition-into-infrastructure",children:"FABLE: It's Not Just About Smarter AI \u2014 It's Turning Expert Intuition into Infrastructure"})}),"\n",(0,i.jsx)(t.p,{children:"Every time AI's intelligence reaches a certain threshold, a qualitative shift occurs \u2014 not doing the same things better, but suddenly doing things that were previously impossible."}),"\n",(0,i.jsx)(t.p,{children:"A few days ago, I had a dream."}),"\n",(0,i.jsx)(t.p,{children:"In the dream, I was in a university auditorium. The seats were packed tight. On stage, some people were performing songs and dances, others were giving speeches. I left my backpack on a seat somewhere, then went up to a mezzanine level to watch for a while. When I came back down, everyone had left. There were still performers on stage, but my backpack was gone."}),"\n",(0,i.jsx)(t.p,{children:"I searched everywhere. Went up to the second floor \u2014 nothing. Up to the third floor \u2014 the top floor turned out to be a park, with children playing on slides and people on swings. The slide could take you back down to the second floor, but the backpack wasn't there either. I went back to the auditorium, circled around the stage, flipped through several rows of chairs. Still nothing."}),"\n",(0,i.jsx)(t.p,{children:"Then something very strange happened."}),"\n",(0,i.jsx)(t.p,{children:"I suddenly remembered where the backpack was. I didn't find it \u2014 I remembered it. And the moment I remembered, the backpack appeared. Right on my back."}),"\n",(0,i.jsx)(t.p,{children:"Then I remembered I'd forgotten my shoes. Same logic: I knew which pair they were, and the shoes appeared in front of me."}),"\n",(0,i.jsx)(t.p,{children:"If you don't know where something is, you'll never find it. If you know where it is, it appears automatically."}),"\n",(0,i.jsx)(t.p,{children:"This isn't the logic of search. This is the logic of recognition."}),"\n",(0,i.jsx)(t.p,{children:"After waking up, I realized that the mechanism of this dream had the same structure as something I'd been thinking about for a while."}),"\n",(0,i.jsx)(t.p,{children:(0,i.jsx)(t.img,{src:n(4426).A+"",width:"2816",height:"1536"})}),"\n",(0,i.jsx)(t.hr,{}),"\n",(0,i.jsx)(t.p,{children:"The AI world loves talking about leaderboards lately."}),"\n",(0,i.jsx)(t.p,{children:"GPT scores this much. Claude scores that much. How close Chinese models are getting. How much reasoning has improved. How much costs have dropped. Every few weeks there's a new benchmark, a new champion, a new ranking. As if AI progress can ultimately be translated into two numbers: capability and price."}),"\n",(0,i.jsx)(t.p,{children:"That's not wrong. Over the past two years, most models have indeed progressed this way \u2014 more accurate answers, fewer hallucinations, longer reasoning chains, better code. Like processors gaining twenty percent each year, graphics cards getting a bit faster. Naturally, people see AI as a continuous upward curve."}),"\n",(0,i.jsx)(t.p,{children:"But some progress doesn't work this way."}),"\n",(0,i.jsx)(t.hr,{}),"\n",(0,i.jsx)(t.p,{children:'Last year, many people talked about Google\'s next-generation image model, saying it "solved the character consistency problem," as if AI could draw the same character for the first time.'}),"\n",(0,i.jsx)(t.p,{children:"Anyone who's used Stable Diffusion would laugh."}),"\n",(0,i.jsx)(t.p,{children:"LoRA can do consistency. IPAdapter can do it. ControlNet can do it. ComfyUI has countless workflows dedicated to this. As long as you're willing to invest time, tweak parameters, and keep retrying, character consistency has always been achievable."}),"\n",(0,i.jsx)(t.p,{children:"The problem was never whether it could be done."}),"\n",(0,i.jsx)(t.p,{children:"The problem was who could do it."}),"\n",(0,i.jsx)(t.p,{children:"Consistency used to belong to a select few. It required extensive experience, understanding of the model, stumbling through countless pitfalls, and building your own workflows. Many people saw others produce entire character sets and assumed the model was powerful. In reality, what was truly powerful was the person behind it."}),"\n",(0,i.jsx)(t.p,{children:"What Google's image model really changed wasn't the capability itself."}),"\n",(0,i.jsx)(t.p,{children:"It turned what used to be an expert-only skill into a natural ability."}),"\n",(0,i.jsx)(t.p,{children:"Before, you needed six months of learning. Now you type one sentence."}),"\n",(0,i.jsx)(t.p,{children:"Before, you had to understand nodes, use IPAdapter or ControlNet to generate images one by one, using the previous image as reference each time \u2014 but errors would accumulate, characters would drift further off-model, and you had to manually pull them back constantly. Now you just give the model an original reference \u2014 even one that's itself AI-generated \u2014 and the model anchors all subsequent variations to that source, without drifting."}),"\n",(0,i.jsx)(t.p,{children:"Before, you had to constantly wrestle between consistency and creative freedom. Now the model handles it."}),"\n",(0,i.jsx)(t.p,{children:"Of course, ComfyUI hasn't been replaced. Local generation still has its value \u2014 ultimate control, uncensored creative freedom, zero marginal cost for batch output. For those who've already mastered the full workflow, ComfyUI remains the more powerful tool. Whether it's worth learning is debatable. But that's precisely the point: before, you had only one path. Now you have a choice. And the new path doesn't cost six months of tuition."}),"\n",(0,i.jsx)(t.p,{children:"This kind of progress is hard to express with benchmarks. It's not going from eighty to ninety points. It's turning a skill that was once scarce into a foundational capability anyone can use."}),"\n",(0,i.jsxs)(t.p,{children:[(0,i.jsx)(t.img,{src:n(7692).A+"",width:"1696",height:"2528"}),"\r\n",(0,i.jsx)(t.img,{src:n(3002).A+"",width:"2752",height:"1536"})]}),"\n",(0,i.jsx)(t.hr,{}),"\n",(0,i.jsx)(t.p,{children:"FABLE gives me a similar feeling. But what I want to talk about isn't leaderboards."}),"\n",(0,i.jsx)(t.p,{children:"I want to talk about something related to the dream at the beginning."}),"\n",(0,i.jsx)(t.p,{children:"Anyone who's done research knows there's one part of academic work that no search engine can help with \u2014 finding papers that the entire academic system has forgotten."}),"\n",(0,i.jsx)(t.p,{children:"Not finding related literature. Related literature can be found with keywords, traced through citation chains, searched on Google Scholar. That's retrieval \u2014 machines have always been able to do that."}),"\n",(0,i.jsx)(t.p,{children:"It's something else entirely."}),"\n",(0,i.jsx)(t.p,{children:"Some research has its value hidden beyond the abstract. The core insight is buried in a derivation in chapter four, in a side observation the author barely mentioned, in a structural similarity between two seemingly unrelated fields. This kind of thing can't be searched by keyword \u2014 because its value isn't defined by the author, but by the reader's knowledge structure."}),"\n",(0,i.jsx)(t.p,{children:"The same paper: one person sees a boring improvement to a statistical method; another sees a core framework applicable to an entirely different field."}),"\n",(0,i.jsx)(t.p,{children:"The difference isn't in the paper. The difference is in the reader's mind."}),"\n",(0,i.jsx)(t.p,{children:"Finding this kind of thing used to have only one method."}),"\n",(0,i.jsx)(t.p,{children:"Go to the library. Browse."}),"\n",(0,i.jsx)(t.p,{children:"Not careful reading \u2014 no one has time to carefully read thousands of papers. It's rapid scanning: flipping through pages, looking at structure, examining charts, seeing how the author handles their data. Most of the time, nothing. Occasionally \u2014 very occasionally \u2014 you'd stop, feeling something was off about a paper. Not that it was poorly written, but that it was written too well \u2014 too well to have so few citations."}),"\n",(0,i.jsx)(t.p,{children:"This feeling is hard to teach. It's not knowledge \u2014 it's intuition."}),"\n",(0,i.jsx)(t.p,{children:"Someone with thirty years of research experience can flip a few pages and know whether a paper has substance. A veteran investor can look at a few numbers and know where the problem lies. A seasoned editor can read the first page and know whether a book has something. Ask them how they judge, and they can't explain. Because it's no longer a method \u2014 it's instinct."}),"\n",(0,i.jsx)(t.p,{children:"This is the same as the backpack in the dream. You searched every row of chairs, went up three floors \u2014 that's searching. But the backpack wasn't found \u2014 it was remembered. Your consciousness aligned with the target, and the thing just appeared."}),"\n",(0,i.jsx)(t.p,{children:"Browsing papers in the library works the same way. You're not searching \u2014 you're waiting for something to trigger your recognition system."}),"\n",(0,i.jsx)(t.p,{children:"And the problems with this approach are all too obvious."}),"\n",(0,i.jsx)(t.p,{children:"It's slow."}),"\n",(0,i.jsx)(t.p,{children:"One cycle takes at least a few months, usually a quarter minimum. And it's highly dependent on luck \u2014 you might miss a paper that was on the next shelf over, never knowing it existed. One person can browse at most a few hundred papers per quarter. Those you didn't get to might as well have never existed."}),"\n",(0,i.jsx)(t.p,{children:"Like the backpack in the dream: if you don't know where it is, you'll never find it."}),"\n",(0,i.jsx)(t.p,{children:"Many people have long felt that AI should be able to solve this."}),"\n",(0,i.jsx)(t.p,{children:"But over the past few years, it hasn't."}),"\n",(0,i.jsx)(t.p,{children:(0,i.jsx)(t.img,{src:n(3530).A+"",width:"2816",height:"1536"})}),"\n",(0,i.jsx)(t.hr,{}),"\n",(0,i.jsx)(t.p,{children:'Not because the models weren\'t smart enough. But because the nature of this problem is fundamentally different from what most people understand as "AI reading papers."'}),"\n",(0,i.jsx)(t.p,{children:'Most people imagine "AI reading papers" like this: you give it a paper, it summarizes the key points and answers questions. Current models can indeed do this, and they\'re getting better. But this is comprehension, not discovery. You already know which paper to read \u2014 you just want to read it faster.'}),"\n",(0,i.jsx)(t.p,{children:"It's like already knowing which restaurant you want to go to, and just wanting the Uber to arrive faster. Very useful, but it's not exploration."}),"\n",(0,i.jsx)(t.p,{children:"People who truly need AI's help don't need to read faster."}),"\n",(0,i.jsx)(t.p,{children:"What they need is: from one hundred thousand unread papers, find three worth diving into."}),"\n",(0,i.jsx)(t.p,{children:'For AI, this is an entirely different problem. It\'s not "understanding a paper" but "identifying incorrectly buried signals in massive noise." This requires not search capability, but judgment \u2014 and judgment has been AI\'s weakest link over the past few years.'}),"\n",(0,i.jsx)(t.p,{children:"There are three reasons."}),"\n",(0,i.jsx)(t.p,{children:"First, all existing academic search tools are consensus-based. Citation counts, impact factors, university rankings, top journals \u2014 these metrics can only find value that the academic community has already acknowledged. But what truly needs to be found is precisely what this system has overlooked. Using consensus tools to find counter-consensus value is logically contradictory. It's like using bestseller lists to find buried geniuses \u2014 bestseller lists are defined by excluding them."}),"\n",(0,i.jsx)(t.p,{children:"Moreover, this system doesn't just passively ignore old research \u2014 it actively buries it. A paper published in 2008 could still be found in university databases back then. But nearly twenty years later, newer papers with higher citations and better rankings keep piling on top, pushing that old paper to page hundreds of the search results \u2014 effectively the same as deletion. Even if you know the author's name, the university, and the research field, you still can't find it. Not because information is hidden, but because information is drowned."}),"\n",(0,i.jsx)(t.p,{children:"Worse still, the sea that's drowning you is itself going rotten."}),"\n",(0,i.jsx)(t.p,{children:"In recent years, the proliferation of AI writing tools has caused academic publication volumes to explode, but much of it consists of homogeneous padding papers and AI-generated fakes. They occupy search results, consume ranking weight, and push already-deep old research even deeper. The needles you're looking for haven't decreased, but the haystack is expanding at unprecedented speed \u2014 and it's starting to include things that look like needles but are actually plastic."}),"\n",(0,i.jsx)(t.p,{children:"Ranking isn't neutral. Ranking is a continuously operating forgetting machine. And now, the fuel for this machine is being supplied at an accelerating rate."}),"\n",(0,i.jsx)(t.p,{children:'Second, RAG and vector search can\'t solve this problem. They\'re fundamentally semantic matching \u2014 finding passages semantically similar to your query. But a buried paper may be buried precisely because its language, framework, and framing are completely different from the mainstream. Semantic search finds "things said similarly," not "things structurally similar but expressed completely differently." If you search for "optimization" in Chinese, it won\'t help you find a paper written in French using entirely different terminology to describe the same mathematical structure.'}),"\n",(0,i.jsx)(t.p,{children:"Third, and most critically: hallucination."}),"\n",(0,i.jsx)(t.p,{children:'AI\'s hallucination problem when reading papers is far more severe than in casual conversation. If you get a wrong answer in chat, you can ask again \u2014 the cost is low. But academic mining is different \u2014 if AI packages a valueless paper as valuable, distorts conclusions, exaggerates findings, or mixes content from two different papers, you might invest months based on that flawed judgment. This year, a large-scale study in the Lancet found that a significant number of AI-generated medical citations are entirely fabricated, and these fake citations have already begun being cited by real papers, forming a pollution chain. The cost of error in academic research isn\'t "getting one question wrong" \u2014 it\'s "wasting a quarter or even a year."'}),"\n",(0,i.jsx)(t.p,{children:'So over the past few years, even as models grew more powerful, researchers\' use of AI has remained at the same level: reading a known paper, summarizing it, answering questions. AI does these well, and many researchers already use it. But "help me read faster" and "help me find something I didn\'t know existed" are two entirely different things. No one has dared entrust the latter to AI, because the cost of misplaced trust is too high.'}),"\n",(0,i.jsx)(t.p,{children:"It's not that no one has tried. Tools like Undermind are already doing similar work \u2014 iterative searching, citation chain tracking, multi-round semantic adjustment, finding papers that standard search misses. GSK, MIT, and Harvard all use it. It's genuinely much better than Google Scholar. But its core method is still an evolved version of retrieval \u2014 searching wider, tracking deeper, filtering more precisely."}),"\n",(0,i.jsx)(t.p,{children:"This is weaving a finer fishing net."}),"\n",(0,i.jsx)(t.p,{children:"But fishing nets are designed to catch big fish. If what you're looking for isn't a big fish, but a specific kind of microorganism \u2014 something hidden in the silt at the ocean floor, invisible to the naked eye, but potentially capable of rewriting an entire field \u2014 then no matter how fine the net, it's useless. What you need isn't a better net. It's a microscope."}),"\n",(0,i.jsx)(t.p,{children:(0,i.jsx)(t.img,{src:n(3219).A+"",width:"2816",height:"1536"})}),"\n",(0,i.jsx)(t.hr,{}),"\n",(0,i.jsx)(t.p,{children:"FABLE is the first thing that makes you feel like maybe you can do more than cast nets \u2014 maybe you can see what nets can't catch."}),"\n",(0,i.jsx)(t.p,{children:"Not because it doesn't hallucinate. Every model does."}),"\n",(0,i.jsx)(t.p,{children:"But because what it does is fundamentally different from previous models."}),"\n",(0,i.jsx)(t.p,{children:"Previous models reading papers were more like summarizing \u2014 extracting keywords, organizing structure, answering questions. FABLE seems to be doing something else: it's building a mental model. After reading a paper, it doesn't just remember the content \u2014 it understands the logical structure: what the author's reasoning chain is, what the core assumptions are, which conclusions are directly derived from data, and which are the author's interpretations."}),"\n",(0,i.jsx)(t.p,{children:"This distinction is critical."}),"\n",(0,i.jsx)(t.p,{children:'Because if an AI can build a mental model, it becomes possible for it to do what those researchers used to do in libraries: not search, but recognize structural value. It could read a statistics paper from 2003 with only three citations and point out: "The optimization method in this paper has structural similarity to the embedded systems resource allocation problem you\'re working on."'}),"\n",(0,i.jsx)(t.p,{children:"This isn't something keyword search can do. It isn't something RAG can do. It isn't even something \"searching wider\" can do."}),"\n",(0,i.jsx)(t.p,{children:"This is judgment."}),"\n",(0,i.jsx)(t.p,{children:'In the language of the dream: this isn\'t rummaging through chairs looking for the backpack. This is the moment of "remembering where the backpack is" \u2014 consciousness aligns with the target, and the thing appears on its own.'}),"\n",(0,i.jsx)(t.p,{children:"And this also redefines the hallucination problem \u2014 not eliminating hallucination, but changing the architecture. The correct approach isn't having AI replace human judgment, but having it do first-pass filtering: narrowing one hundred thousand papers down to one hundred, then humans review them. Researchers' problem has never been \"can't understand\" \u2014 it's \"can't find.\" A sufficiently experienced person is perfectly capable of judging whether a paper is worth diving into. What they lack is the bandwidth to encounter it in the first place."}),"\n",(0,i.jsx)(t.p,{children:"So the real workflow is two-layered. AI does reconnaissance; humans make judgments. The risk of hallucination is drastically reduced in this architecture \u2014 because you're not blindly trusting its conclusions; you're using it to expand your search scope, then applying your own expertise for final verification. FABLE's value isn't \"it doesn't hallucinate\" \u2014 it's that its understanding runs deep enough that what it filters out has a hit rate high enough to justify the time spent on manual verification."}),"\n",(0,i.jsx)(t.p,{children:"This is really just a scaled version of the old library method. Before, you didn't carefully read every paper either \u2014 you scanned rapidly, filtered by intuition, picked a few to go deep on. The difference is that before it was a few hundred papers per quarter. Now it's thousands per day."}),"\n",(0,i.jsx)(t.p,{children:"The library hasn't shrunk \u2014 it's expanding at unprecedented speed. It's just that most of what's being added isn't books. It's noise."}),"\n",(0,i.jsx)(t.p,{children:"But you have more eyes now."}),"\n",(0,i.jsx)(t.p,{children:(0,i.jsx)(t.img,{src:n(5670).A+"",width:"2816",height:"1536"})}),"\n",(0,i.jsx)(t.hr,{}),"\n",(0,i.jsx)(t.p,{children:"If you look at it from this angle, what FABLE demonstrates isn't a higher IQ."}),"\n",(0,i.jsx)(t.p,{children:"What it demonstrates is a new direction."}),"\n",(0,i.jsx)(t.p,{children:"AlphaGo's value wasn't making chess cheaper. Google's image model's value wasn't generating images faster. If FABLE truly demonstrates anything, it's not higher reasoning scores."}),"\n",(0,i.jsx)(t.p,{children:"What it demonstrates is that certain cognitive abilities that once belonged only to a select few may, for the first time, become infrastructure."}),"\n",(0,i.jsx)(t.p,{children:"In the past, infrastructure solved physical problems. Electricity gave everyone the power of machines. The internet gave everyone the power of information."}),"\n",(0,i.jsx)(t.p,{children:"The next generation of AI may be doing something else entirely."}),"\n",(0,i.jsx)(t.p,{children:"It's turning expert intuition into infrastructure."}),"\n",(0,i.jsx)(t.p,{children:"Before, you needed thirty years of experience, cross-disciplinary knowledge, massive amounts of reading, sharp intuition, and even a bit of luck to fish out forgotten value from the blind spots of the academic system."}),"\n",(0,i.jsx)(t.p,{children:"If one day, a researcher just starting out can do something similar through AI \u2014 not exactly the same, but at least close \u2014 then what AI changes isn't just efficiency."}),"\n",(0,i.jsx)(t.p,{children:"What it changes is the distribution of opportunity."}),"\n",(0,i.jsx)(t.p,{children:"Because the most important question of the future may not be which model is smarter."}),"\n",(0,i.jsx)(t.p,{children:"It may be which scarce human capabilities it makes universally accessible for the first time."}),"\n",(0,i.jsx)(t.p,{children:"Like the final scene of the dream. You no longer need to search the entire auditorium."}),"\n",(0,i.jsx)(t.p,{children:"You just need to remember."}),"\n",(0,i.jsx)(t.p,{children:"And AI is learning how to help you remember."}),"\n",(0,i.jsx)(t.p,{children:(0,i.jsx)(t.img,{src:n(3948).A+"",width:"2816",height:"1536"})})]})}function l(e={}){const{wrapper:t}={...(0,s.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(c,{...e})}):c(e)}},3219(e,t,n){n.d(t,{A:()=>i});const i=n.p+"assets/images/Gemini_Generated_Image_1j661h1j661h1j66-8f3f77e78d60ed538aa0687d5876ebde.png"},3948(e,t,n){n.d(t,{A:()=>i});const i=n.p+"assets/images/Gemini_Generated_Image_4477e44477e44477-9d8a98177db07edffa92a2b3122d3498.png"},5670(e,t,n){n.d(t,{A:()=>i});const i=n.p+"assets/images/Gemini_Generated_Image_7sx2957sx2957sx2-47a084f677fdcd25702b637e48158126.png"},3002(e,t,n){n.d(t,{A:()=>i});const i=n.p+"assets/images/Gemini_Generated_Image_8cgnb78cgnb78cgn-4a6c74bcd52db18fb77cc66dc64bdc86.png"},4426(e,t,n){n.d(t,{A:()=>i});const i=n.p+"assets/images/Gemini_Generated_Image_eck9akeck9akeck9-382adcab65b14e1876fa15a261d0e4c2.png"},3530(e,t,n){n.d(t,{A:()=>i});const i=n.p+"assets/images/Gemini_Generated_Image_vj5c20vj5c20vj5c-1ec88674a6aeb784c0d71cb864a94974.png"},7692(e,t,n){n.d(t,{A:()=>i});const i=n.p+"assets/images/Gemini_Generated_Image_zengyhzengyhzeng-ceb78a7e558dffe629604c454d04ccee.png"},8453(e,t,n){n.d(t,{R:()=>r,x:()=>o});var i=n(6540);const s={},a=i.createContext(s);function r(e){const t=i.useContext(a);return i.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function o(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:r(e.components),i.createElement(a.Provider,{value:t},e.children)}}}]);